SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, status, APPROX_PERCENTILE(shipping_fee, 0.9) AS shipping_fee_p90, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows, SUM(shipping_fee) AS total_shipping_fee, COUNT_IF(status = 'SHIPPED') AS shipped_events, COUNT(DISTINCT store_id) AS distinct_store_ids, COUNT(*) AS row_count, GROUPING_ID() AS grouping_level FROM orders GROUP BY CUBE (DATE_TRUNC('MONTH', order_date), status) ORDER BY row_count DESC;
